        {toasts.map((t) => (
          <div key={t.id} style={{ background: "#333", color: "#fff",
              padding: "8px 12px", marginTop: 8, borderRadius: 4 }}>
            {t.message}
          </div>
        ))}
      </div>
    </ToastContext.Provider>
  );
}

export function useToast() {
  return useContext(ToastContext);
}
```

