Here's a working minimal platformer in p5.js (global mode). It has gravity, jumping, a ground, and a couple of platforms. It's Mario-*style*, not actual Mario art or levels.

```javascript
let player = { x: 60, y: 0, w: 30, h: 40, vx: 0, vy: 0, onGround: false };
let platforms = [];
const GRAVITY = 0.6, SPEED = 4, JUMP = -12;

function setup() {
  createCanvas(640, 400);
  platforms = [
    { x: 0, y: 360, w: 640, h: 40 },   // ground
    { x: 150, y: 280, w: 120, h: 15 },
    { x: 380, y: 210, w: 120, h: 15 }
  ];
  player.y = 360 - player.h;
}

function draw() {
  background(135, 206, 235);

  // horizontal input
  player.vx = 0;
  if (keyIsDown(LEFT_ARROW))  player.vx = -SPEED;
  if (keyIsDown(RIGHT_ARROW)) player.vx =  SPEED;
  player.x += player.vx;

  // vertical physics
  player.vy += GRAVITY;
  player.y += player.vy;
  player.onGround = false;

  // collisions
  for (let p of platforms) {
    if (player.x + player.w > p.x && player.x < p.x + p.w &&
        player.y + player.h > p.y && player.y < p.y + p.h) {
      if (player.vy >= 0 && player.y + player.h - player.vy <= p.y) {
        player.y = p.y - player.h;
        player.vy = 0;
        player.onGround = true;
      }
    }
  }

  // keep on screen
  player.x = constrain(player.x, 0, width - player.w);

  // draw
  for (let p of platforms) {
    fill(80, 160, 60);
    rect(p.x, p.y, p.w, p.h);
  }
  fill(220, 50, 50);
  rect(player.x, player.y, player.w, player.h);
}

function keyPressed() {
  if (keyCode === UP_ARROW && player.onGround) {
    player.vy = JUMP;
  }
}
```

Honest notes:
- I used a rectangle instead of Mario art (Nintendo's sprites are copyrighted).
- This is one screen, no enemies, coins, or scrolling. Those are each a real chunk of work.
- I haven't run this, so treat it as a solid starting point — check it in the p5 web editor and tell me what breaks.

