The standard way is a JAX-WS `SOAPHandler<SOAPMessageContext>`, registered on the client or server. It sees the full SOAP envelope, so you can log both directions.

```java
import java.io.*;
import java.util.*;
import javax.xml.namespace.QName;
import javax.xml.ws.handler.*;
import javax.xml.ws.handler.soap.*;
import javax.xml.transform.*;
import javax.xml.transform.stream.*;
import javax.xml.transform.dom.DOMSource;

public class LoggingHandler implements SOAPHandler<SOAPMessageContext> {
    private static void dump(SOAPMessageContext ctx, boolean outbound) {
        try {
            System.out.println(outbound ? "--- request ---" : "--- response ---");
            ctx.getMessage().writeTo(System.out);
            System.out.println();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

